func (o *XdgPopup) Configure(x int32, y int32, width int32, height int32) {
	o.send(0, x, y, width, height)
}

func (o *XdgPopup) PopupDone() {
	o.send(1)
}

func (o *XdgPopup) Repositioned(token uint32) {
	o.send(2, token)
}

